def get_lesson_context(call_id: str):
    """Resolve lesson metadata from call_id."""
    # call_id format: audio_{lesson_id}_{user_id} e.g. audio_ja-u1-l1_user_...
    parts = call_id.replace("audio_", "").split("_")
    lesson_id = parts[0] if parts else ""
    
    if lesson_id in LESSONS_DATA:
        return LESSONS_DATA[lesson_id]
        
    lang_code = lesson_id.split("-")[0] if "-" in lesson_id else "ja"
    lang_info = LANGUAGES_DEFAULT.get(lang_code, LANGUAGES_DEFAULT["ja"])
    
    return {
        "id": lesson_id,
        "title": "Language Practice",
        "languageCode": lang_code,
        "languageName": lang_info["name"],
        "welcomeMessage": lang_info["welcome"],
        "systemPrompt": lang_info["default_prompt"],
        "vocabulary": [],
        "phrases": [],
    }
